insert into public.exercises (id, slug, name, category, equipment, primary_muscles, short_cue, common_mistake, regression, progression, description, source_name, source_url, source_match_type, source_notes) values
('bbbbbbbb-bbbb-bbbb-bbbb-000000000001', 'modified-burpee', 'Modified Burpee', 'conditioning', 'None', ARRAY['Full body','Core'], 'Squat down, step back to plank, step in, stand tall.', 'Letting hips sag in plank.', 'Hands on bench.', 'Add small hop.', 'A step-back burpee that builds conditioning without requiring a jump. Squat, place hands down, step to plank, step in, and stand tall.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/squat-thrust-burpees', 'close variation', 'Use step-back/no-jump regression'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000002', 'alternating-step-up', 'Alternating Step-Up', 'legs', 'Sturdy step or bench', ARRAY['Quads','Glutes'], 'Step through heel, stand tall, control down.', 'Pushing off the floor leg too much.', 'Lower step.', 'Add knee drive.', 'Step onto a sturdy platform, stand tall, then lower with control. Alternate legs and count both sides toward the total.', 'ACE', 'https://www.acefitness.org/resources/everyone/exercise-library/28/step-up/', 'exact', 'Use as controlled step-up demo'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000003', 'incline-diamond-push-up', 'Incline Diamond Push-Up', 'push', 'Bench, counter, or wall', ARRAY['Chest','Triceps','Shoulders'], 'Hands narrow on incline, body straight, lower chest as one piece.', 'Flaring elbows hard or dropping hips.', 'Higher incline.', 'Lower incline.', 'Hands close together in a diamond shape on an incline surface. Keep the body straight and lower the chest as one piece.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/incline-push-up', 'close variation', 'Same incline setup, use narrow/diamond hands'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000004', 'wide-push-up', 'Wide Push-Up', 'push', 'None', ARRAY['Chest','Shoulders','Core'], 'Hands wide, brace, lower chest, press away.', 'Neck reaching toward floor.', 'Knees down.', 'Tempo lowering.', 'A push-up with hands wider than shoulders. Brace the core, lower the chest, and press away.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/push-up', 'base movement', 'Same push-up mechanics, wider hands'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000005', 'reverse-crunch', 'Reverse Crunch', 'core', 'None', ARRAY['Abs'], 'Curl hips up using abs, lower with control.', 'Swinging legs.', 'Smaller curl.', 'Add pause at top.', 'Lie on your back and curl the pelvis toward the ribs using your abs. Lower with control instead of swinging the legs.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/reverse-crunch-to-knee-up-with-rotation', 'close variation', 'Omit rotation for this program'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000006', 'scissor-kick', 'Scissor Kick', 'core', 'None', ARRAY['Abs','Hip flexors'], 'Brace low back, alternate legs smoothly.', 'Arching low back.', 'Keep legs higher.', 'Lower legs closer to floor.', 'Lie on your back with the low back braced. Alternate legs in a smooth scissor pattern while keeping the torso quiet.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/dead-bug', 'base movement', 'Use for core bracing reference; replace with exact accredited video if found'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000007', 'prone-cobra', 'Prone Cobra', 'pull', 'None', ARRAY['Upper back','Rear shoulders'], 'Lift chest lightly, thumbs rotate up, squeeze shoulder blades.', 'Cranking neck up.', 'Smaller lift.', 'Longer hold.', 'Lie face down, lift the chest lightly, rotate thumbs up, and squeeze the shoulder blades before lowering.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/floor-prone-cobra', 'exact', 'No equipment'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000008', 'single-leg-glute-bridge', 'Single-Leg Glute Bridge', 'legs', 'None', ARRAY['Glutes','Hamstrings'], 'Drive through heel, keep hips level.', 'Twisting hips.', 'Two-leg bridge.', 'Longer top hold.', 'Lie on your back, lift one leg, and drive through the planted heel to raise the hips while keeping them level.', 'ACE', 'https://www.acefitness.org/resources/everyone/exercise-library/145/glute-bridge-single-leg-progression/', 'exact', 'Single-leg bridge progression'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000009', 'step-up', 'Step-Up', 'legs', 'Sturdy step or bench', ARRAY['Quads','Glutes'], 'Place full foot on step, stand tall, lower slow.', 'Knee collapsing inward.', 'Lower step.', 'Hold light dumbbells.', 'Place a full foot on a raised platform, stand tall, then lower slowly. Alternate sides toward the total count.', 'ACE', 'https://www.acefitness.org/resources/everyone/exercise-library/28/step-up/', 'exact', 'Raised platform/box'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000010', 'cross-body-mountain-climber', 'Cross-Body Mountain Climber', 'conditioning', 'None', ARRAY['Core','Shoulders','Hip flexors'], 'High plank, knee toward opposite elbow, switch.', 'Bouncing hips high.', 'Slow taps.', 'Faster tempo.', 'From a high plank, drive one knee toward the opposite elbow, then switch sides with control.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/straight-arm-plank', 'base movement', 'Use plank setup and add cross-body knee drive'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000011', 'burpee', 'Burpee', 'conditioning', 'None', ARRAY['Full body'], 'Squat, plank, return, stand or jump.', 'Landing hard.', 'Step-back modified burpee.', 'Add push-up.', 'Squat, move to plank, return, then stand or jump. Use the full version when form stays solid.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/squat-thrust-burpees', 'exact', 'NASM labels squat thrust burpees'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000012', 'forearm-plank', 'Forearm Plank', 'core', 'None', ARRAY['Core','Shoulders'], 'Elbows under shoulders, squeeze glutes, breathe.', 'Hips sagging.', 'Knees down.', 'Longer hold.', 'Hold a straight line on the forearms with elbows under the shoulders. Squeeze glutes and breathe steadily.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/plank', 'exact', 'Time-based hold'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000013', 'squat-press', 'Squat Press', 'full body', 'None (optional light dumbbells)', ARRAY['Quads','Glutes','Shoulders'], 'Squat, stand, reach/press overhead.', 'Rounding back.', 'Squat to chair.', 'Add light dumbbells.', 'Bodyweight squat, then reach or press overhead as you stand. Keep the torso upright and the motion smooth.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/prisoner-squat', 'base movement', 'Use squat mechanics, add overhead reach/press'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000014', 'squat-thrust', 'Squat Thrust', 'conditioning', 'None', ARRAY['Full body','Core'], 'Hands down, feet back to plank, feet in, stand.', 'Letting shoulders collapse.', 'Step feet one at a time.', 'Add jump.', 'Hands down, feet back to plank, feet in, stand. No push-up required for this variation.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/squat-thrust-burpees', 'exact', 'No push-up required for this variation'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000015', 'skater-squat', 'Skater Squat', 'legs', 'None', ARRAY['Glutes','Quads','Lateral hips'], 'Shift to one side, control knee, push back up.', 'Knee diving inward.', 'Shorter range.', 'Reach opposite foot behind.', 'A controlled side-to-side or single-leg pattern. Shift to one side, control the knee, and push back up.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/single-leg-squat-touchdown', 'close variation', 'Similar single-leg control'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000016', 'wide-stance-calf-raise', 'Wide-Stance Calf Raise', 'legs', 'None', ARRAY['Calves'], 'Feet wide, rise onto balls of feet, lower slow.', 'Rolling ankles outward.', 'Hold wall.', 'Add pause at top.', 'Stand with feet wide, rise onto the balls of the feet, then lower slowly under control.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/leg-press-calf-raise', 'base movement', 'Calf raise mechanics; app describes standing bodyweight version'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000017', 'elbow-walkout', 'Elbow Walkout', 'core', 'None', ARRAY['Core','Shoulders'], 'Move between elbow/high plank or walk hands out with control.', 'Rocking hips side to side.', 'Fewer steps.', 'Add pause in plank.', 'Move between elbow and high plank, or walk the hands out with control while keeping the hips steady.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/plank-walkup', 'close variation', 'Similar plank transition'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000018', 'good-morning-hip-hinge', 'Good Morning / Hip Hinge', 'posterior chain', 'None', ARRAY['Hamstrings','Glutes','Back'], 'Soft knees, push hips back, stand by squeezing glutes.', 'Squatting instead of hinging.', 'Hands on hips.', 'Hold light weight.', 'Soft knees, push the hips back with a neutral spine, then stand by squeezing the glutes. Default to bodyweight.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/good-mornings', 'base movement', 'App defaults to bodyweight hip hinge'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000019', 'sit-up-or-crunch', 'Sit-Up or Crunch', 'core', 'None', ARRAY['Abs'], 'Curl ribs toward pelvis, keep neck relaxed.', 'Pulling head with hands.', 'Smaller crunch.', 'Slow tempo.', 'Curl the ribs toward the pelvis with a relaxed neck. Crunch is the beginner default for this program.', 'ACE', 'https://www.acefitness.org/resources/everyone/exercise-library/52/crunch/', 'exact', 'Crunch is beginner default'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000020', 'bent-knee-leg-raise', 'Bent-Knee Leg Raise', 'core', 'None', ARRAY['Abs','Hip flexors'], 'Knees bent, lift hips/legs, lower slowly.', 'Lower back arching.', 'One leg at a time.', 'Extend legs more.', 'Lie on your back with knees bent. Lift the hips or legs, then lower slowly without arching the low back.', 'ACE', 'https://www.acefitness.org/resources/everyone/exercise-library/238/supine-reverse-marches/', 'close variation', 'Similar bent-knee lower-ab control'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000021', 'inverted-row', 'Inverted Row', 'pull', 'Sturdy table, bar, or TRX', ARRAY['Back','Biceps','Rear shoulders'], 'Straight body, pull chest to bar/table, lower with control.', 'Shrugging shoulders.', 'Higher bar angle.', 'Feet farther forward.', 'Keep a straight body line and pull the chest toward a bar, table edge, or suspension handles, then lower with control.', 'NASM', 'https://blog.nasm.org/three-awesome-row-exercise-variations', 'exact article', 'NASM article includes inverted-row technique'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000022', 'side-lunge', 'Side Lunge', 'legs', 'None', ARRAY['Glutes','Quads','Adductors'], 'Step side, hips back, push through planted foot.', 'Step too wide.', 'Smaller step.', 'Add reach or weight.', 'Step to the side, sit the hips back, then push through the planted foot to return. Alternate sides.', 'ACE', 'https://www.acefitness.org/resources/everyone/exercise-library/50/side-lunge/', 'exact', 'No equipment'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000023', 'walking-lunge', 'Walking Lunge', 'legs', 'None', ARRAY['Quads','Glutes'], 'Step forward, lower with control, drive to next step.', 'Front knee caving inward.', 'Stationary lunge.', 'Add light dumbbells.', 'Step forward into a lunge, lower with control, then drive into the next step. Keep the torso tall.', 'ACE', 'https://www.acefitness.org/resources/everyone/exercise-library/94/forward-lunge/', 'base movement', 'Use forward lunge mechanics, repeat as walking reps'),
('bbbbbbbb-bbbb-bbbb-bbbb-000000000024', 'plank-shoulder-tap', 'Plank Shoulder Tap', 'core', 'None', ARRAY['Core','Shoulders'], 'High plank, tap opposite shoulder, keep hips quiet.', 'Rotating hips.', 'Wider feet.', 'Narrow feet.', 'From a high plank, tap the opposite shoulder while keeping the hips as quiet as possible.', 'NASM', 'https://www.nasm.org/resource-center/exercise-library/straight-arm-plank', 'base movement', 'Add alternating shoulder taps from high plank');
